/*
 * A264102  Numbers n with the property that the symmetric representation of
 *          sigma(n) has four parts, each of width one.
 * https://oeis.org/A264102
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   a(n) = the nth integer n satisfying * n = 2^m * p * q, * m ≥ 0,
 *            * p > 2 is prime, * q is prime or q = p^2, * 2^(m+1) < p <
 *            2^(m+1)*p < q (for q prime) or 2^(m+1) < p < q (for q = p^2) *
 *            The sequence is generated by searching n in ascending order
 * Range:     u8 n <= 41, u16 n <= 58, u32 n <= 58, u64 n <= 58, u128 n <= 58,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

typedef uint64_t idx_t;          /* to match build definitions */

/* ------------------------------------------------------------------------ */
/*  Sieve of Eratosthenes for smallest prime factors                         */
/* ------------------------------------------------------------------------ */
static const uint32_t MAX_N = 20000000U;    /* 20 M ≈ 80 MB for uint32_t SPF array  */
static uint32_t *spf = NULL;               /* smallest prime factor table      */

static void init_spf(void)
{
    if (spf != NULL) return;
    spf = (uint32_t *)malloc((MAX_N + 1) * sizeof(uint32_t));
    if (spf == NULL) exit(1);            /* abort on bad allocation */
    for (uint32_t i = 0; i <= MAX_N; ++i) spf[i] = 0;
    for (uint32_t i = 2; i <= MAX_N; ++i) {
        if (spf[i] != 0) continue;
        spf[i] = i;
        if ((uint64_t)i * i > MAX_N) continue;
        for (uint32_t j = i * i; j <= MAX_N; j += i)
            if (spf[j] == 0) spf[j] = i;
    }
}

/* ------------------------------------------------------------------------ */
/*  Test whether an integer x satisfies the sequence condition              */
/* ------------------------------------------------------------------------ */
static bool is_in_sequence(uint32_t x)
{
    uint32_t t = x;
    uint32_t m = 0;
    while ((t & 1) == 0) { ++m; t >>= 1; }
    if (t == 1) return false;              /* no odd prime factor */

    /* find smallest odd prime factor p1 and its exponent exp1 */
    uint32_t p1 = spf[t];
    if (p1 == 0) return false;            /* should never happen */
    uint32_t exp1 = 0;
    uint32_t rem = t;
    while (rem % p1 == 0) { rem /= p1; ++exp1; }

    /* Case 1 : only one odd prime factor (p^3) */
    if (rem == 1) {
        if (exp1 != 3) return false;
        uint32_t thresh = 1u << (m + 1);   /* 2^(m+1) */
        if (p1 > thresh) return true;
        return false;
    }

    /* Case 2 : two distinct odd primes p and q, each exponent 1 */
    if (exp1 != 1) return false;
    /* rem must be prime */
    if (spf[rem] != rem) return false;
    uint32_t p = p1, q = rem;
    if (p > q) { uint32_t tmp = p; p = q; q = tmp; }

    uint32_t thresh = 1u << (m + 1);       /* 2^(m+1) */
    if (p <= thresh) return false;        /* p must be greater than threshold */

    /* q > thresh * p  (i.e., 2^(m+1) * p < q) */
    uint64_t prod = (uint64_t)thresh * (uint64_t)p;
    if (q <= prod) return false;

    return true;
}

/* ------------------------------------------------------------------------ */
/*  Storage for the sequence a(1), a(2), ...                              */
/* ------------------------------------------------------------------------ */
static seq_t *seq  = NULL;   /* dynamic array of sequence terms */
static size_t seq_cap = 0;
static size_t seq_len = 0;
static uint32_t scanned = 0; /* largest n already scanned */

/* Grow the dynamic array if needed */
static void ensure_seq_cap(size_t needed)
{
    if (needed <= seq_cap) return;
    size_t new_cap = seq_cap == 0 ? 128 : seq_cap;
    while (new_cap < needed) new_cap <<= 1;
    seq_t *tmp = (seq_t *)realloc(seq, new_cap * sizeof(seq_t));
    if (tmp == NULL) exit(1);
    seq = tmp;
    seq_cap = new_cap;
}

/* ------------------------------------------------------------------------ */
/*  Main public function                                                    */
/* ------------------------------------------------------------------------ */
seq_t a(idx_t n)
{
    init_spf();                    /* ensure SPF table is ready */

    /* Scan until we have enough terms */
    while (seq_len < n) {
        if (scanned <= MAX_N) ++scanned;
        else {
            /* If the precomputed limit is exhausted without enough terms,
               the sequence would have to contain numbers larger than MAX_N.
               That condition is extraordinarily unlikely for n ≤ 10 000,
               so we abort. */
            exit(1);
        }

        if (is_in_sequence(scanned)) {
            ensure_seq_cap(seq_len + 1);
            seq[seq_len++] = (seq_t)scanned;
        }
    }
    return seq[n - 1];
}
